import java.io.*;
import java.util.*;

public class Main {
    static final int CENTROID_LEVELS = 20;
    static final int UP_LEVELS = 19;
    static final int INF = 1_000_000_000;

    static int n, k;
    static int[] head, to, next;
    static int edgeCount;

    static int[] depth, parent;
    static int[][] up;
    static int[] sortedNodes;

    static int[] centroidAncestors, centroidDistances, centroidCount;
    static int[] nearestCenter;
    static boolean[] removed;

    static int[] workStack, componentNodes, tempParent, subtreeSize, tempDistance;

    static void addEdge(int a, int b) {
        to[edgeCount] = b;
        next[edgeCount] = head[a];
        head[a] = edgeCount++;
    }

    static void buildCentroid(int start, int level) {
        int size = 0, stackSize = 0;
        workStack[stackSize++] = start;
        tempParent[start] = -1;

        while (stackSize > 0) {
            int u = workStack[--stackSize];
            componentNodes[size++] = u;
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!removed[v] && v != tempParent[u]) {
                    tempParent[v] = u;
                    workStack[stackSize++] = v;
                }
            }
        }

        for (int i = size - 1; i >= 0; i--) {
            int u = componentNodes[i];
            subtreeSize[u] = 1;
            if (tempParent[u] != -1) {
                subtreeSize[tempParent[u]] += subtreeSize[u];
            }
        }

        int centroid = start;
        for (int i = 0; i < size; i++) {
            int u = componentNodes[i];
            int largestPart = size - subtreeSize[u];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!removed[v] && tempParent[v] == u) {
                    largestPart = Math.max(largestPart, subtreeSize[v]);
                }
            }
            if (largestPart * 2 <= size) {
                centroid = u;
                break;
            }
        }

        removed[centroid] = true;

        stackSize = 0;
        workStack[stackSize++] = centroid;
        tempParent[centroid] = -1;
        tempDistance[centroid] = 0;

        while (stackSize > 0) {
            int u = workStack[--stackSize];
            int index = u * CENTROID_LEVELS + level;
            centroidAncestors[index] = centroid;
            centroidDistances[index] = tempDistance[u];
            centroidCount[u] = level + 1;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!removed[v] && v != tempParent[u]) {
                    tempParent[v] = u;
                    tempDistance[v] = tempDistance[u] + 1;
                    workStack[stackSize++] = v;
                }
            }
        }

        for (int e = head[centroid]; e != -1; e = next[e]) {
            int v = to[e];
            if (!removed[v]) {
                buildCentroid(v, level + 1);
            }
        }
    }

    static int lift(int node, int distance) {
        int bit = 0;
        while (distance > 0) {
            if ((distance & 1) != 0) {
                node = up[bit][node];
            }
            distance >>= 1;
            bit++;
        }
        return node;
    }

    static boolean feasible(int radius) {
        Arrays.fill(nearestCenter, INF);
        int centers = 0;

        for (int i = n - 1; i >= 0; i--) {
            int u = sortedNodes[i];
            int base = u * CENTROID_LEVELS;
            int best = INF;

            for (int level = 0; level < centroidCount[u]; level++) {
                int index = base + level;
                int c = centroidAncestors[index];
                best = Math.min(best, centroidDistances[index] + nearestCenter[c]);
            }

            if (best > radius) {
                if (++centers > k) {
                    return false;
                }

                int climb = Math.min(radius, depth[u]);
                int center = lift(u, climb);
                base = center * CENTROID_LEVELS;

                for (int level = 0; level < centroidCount[center]; level++) {
                    int index = base + level;
                    int c = centroidAncestors[index];
                    nearestCenter[c] = Math.min(nearestCenter[c], centroidDistances[index]);
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
