            int u = bfs[front++];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v != parent[u]) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    bfs[back++] = v;
                }
            }
        }

        up = new int[UP_LEVELS][n];
        System.arraycopy(parent, 0, up[0], 0, n);
        for (int level = 1; level < UP_LEVELS; level++) {
            int[] previous = up[level - 1];
            int[] current = up[level];
            for (int u = 0; u < n; u++) {
                current[u] = previous[previous[u]];
            }
        }

        int maxDepth = 0;
        for (int d : depth) maxDepth = Math.max(maxDepth, d);
        int[] count = new int[maxDepth + 1];
        for (int d : depth) count[d]++;
        int sum = 0;
        for (int d = 0; d <= maxDepth; d++) {
            int amount = count[d];
            count[d] = sum;
            sum += amount;
        }
        sortedNodes = new int[n];
        for (int u : bfs) {
            sortedNodes[count[depth[u]]++] = u;
        }

        centroidAncestors = new int[n * CENTROID_LEVELS];
        centroidDistances = new int[n * CENTROID_LEVELS];
        centroidCount = new int[n];
        nearestCenter = new int[n];
        removed = new boolean[n];

        workStack = new int[n];
        componentNodes = new int[n];
        tempParent = new int[n];
        subtreeSize = new int[n];
        tempDistance = new int[n];

        buildCentroid(0, 0);

        int low = -1, high = n - 1;
        while (high - low > 1) {
            int mid = (low + high) >>> 1;
            if (feasible(mid)) high = mid;
            else low = mid;
        }

        System.out.println(high);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }
